package workbench.kotlin.l04.demo;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Java twin of BuildersDemo.kt. Java builds a mutable collection, then copies it into an
 * unmodifiable one. buildList and buildString are inline-only Kotlin functions, so Java can't call them.
 */
public class BuildersDemoJava {

    record ItemJava(String sku, int qty, long unitMinor) {}

    public static void main(String[] args) {
        List<ItemJava> building = new ArrayList<>();
        building.add(new ItemJava("sku-1", 2, 999));
        building.add(new ItemJava("sku-2", 1, 500));
        if (building.size() == 2) building.add(new ItemJava("gift-wrap", 1, 0));
        List<ItemJava> items = List.copyOf(building);

        Map<String, Long> totals = new LinkedHashMap<>();
        for (ItemJava i : items) totals.put(i.sku(), i.qty() * i.unitMinor());

        String text = new StringBuilder()
                .append("total=")
                .append(totals.values().stream().mapToLong(Long::longValue).sum())
                .toString();

        System.out.println(items.stream().map(ItemJava::sku).toList());
        System.out.println(totals);
        System.out.println(text);
        try {
            items.add(new ItemJava("late", 1, 1));
        } catch (UnsupportedOperationException e) {
            System.out.println("the copied list is read-only: " + e.getClass().getSimpleName());
        }
    }
}

sections.body:
Nesting creates a trap. Inside `payer { }` two receivers are in scope: the `PartyBuilder` and the outer `PaymentRequestBuilder`. Kotlin resolves an unqualified call against all of them, nearest first. So `payee { }` written inside `payer { }` compiles, because it finds `payee` on the outer builder. In the demo, without a marker, that misplaced line builds a second party and the program fails at run time with `IllegalArgumentException: iban required for 'oops'`. In a DSL without a required field, it would simply build the wrong request.

`@DslMarker` closes the hole. Annotate an annotation class with it, then put that annotation on every builder class. From then on, inside a block only the nearest marked receiver is implicit:

```java
// Java needs no marker: each lambda names its builder, so reaching the outer one takes `r.`
DslMarkerDemoKt.paymentRequest("PR-1", r -> {
    r.payer(p -> {
        p.setName("ACME Ltd");
        r.setCurrency("EUR");          // deliberate, and visible in review
        return Unit.INSTANCE;
    });
    return Unit.INSTANCE;
});
```

```kotlin
@DslMarker
@Target(AnnotationTarget.CLASS, AnnotationTarget.TYPE)
annotation class PaymentDsl

@PaymentDsl class PartyBuilder { /* ... */ }
@PaymentDsl class PaymentRequestBuilder(private val id: String) { /* ... */ }

paymentRequest("PR-2") {
    payer {
        name = "ACME Ltd"
        payee { name = "oops" }                 // error: cannot be called in this context with an implicit receiver
        this@paymentRequest.currency = "EUR"    // an explicit label still works
    }
}
```

The full message is `'fun payee(block: PartyBuilder.() -> Unit): Unit' cannot be called in this context with an implicit receiver. Use an explicit receiver if necessary.` The label `this@paymentRequest` uses the name of the function that took the lambda, and nobody types it by accident.

The rules are narrow, so learn them exactly. The docs say a marker counts only on classes, on the receiver types of function types (the `TYPE` target, as in `@PaymentDsl PartyBuilder.() -> Unit`) and on type aliases. On a function or a property it "has no effect". Marking a common superclass is enough, so a DSL with twenty builders can mark one base class. And extension functions on a marked builder still work inside its block, because they resolve against the nearest receiver.

code.src:
package workbench.kotlin.l04.demo

@DslMarker
@Target(AnnotationTarget.CLASS, AnnotationTarget.TYPE)
annotation class PaymentDsl

data class Party(val name: String, val iban: String)

data class PaymentRequest(val id: String, val currency: String, val payer: Party, val payee: Party)

@PaymentDsl
class PartyBuilder {
    var name = ""
    var iban = ""

    fun build(): Party {
        require(iban.isNotBlank()) { "iban required for '$name'" }
        return Party(name, iban)
    }
}

@PaymentDsl
class PaymentRequestBuilder(private val id: String) {
    var currency = "EUR"
    private var payer: Party? = null
    private var payee: Party? = null

    fun payer(block: PartyBuilder.() -> Unit) { payer = PartyBuilder().apply(block).build() }

    fun payee(block: PartyBuilder.() -> Unit) { payee = PartyBuilder().apply(block).build() }

    fun build() = PaymentRequest(id, currency, checkNotNull(payer) { "payer missing" }, checkNotNull(payee) { "payee missing" })
}

fun paymentRequest(id: String, block: PaymentRequestBuilder.() -> Unit): PaymentRequest =
    PaymentRequestBuilder(id).apply(block).build()

fun main() {
    val req = paymentRequest("PR-1") {
        currency = "GBP"
        payer { name = "ACME Ltd"; iban = "GB33BUKB20201555555555" }
        payee {
            name = "Corner Shop"
            iban = "GB94BARC10201530093459"
            this@paymentRequest.currency = "EUR"      // an outer receiver needs an explicit label
        }
    }
    println(req)

    // Wrong move. Uncomment the block, predict, run. Then remove @PaymentDsl from both builder
    // classes and run it again.
    // paymentRequest("PR-2") {
    //     payer {
    //         name = "ACME Ltd"
    //         payee { name = "oops" }
    //         iban = "GB33BUKB20201555555555"
    //     }
    // }
}

