fun EntryBuilder.payout(merchant: String, grossMinor: Long, feeBps: Int) {
    val fee = grossMinor * feeBps / 10_000
    // 2. the three postings, always balanced
    debit("merchant:$merchant", grossMinor)
    credit("bank:clearing", grossMinor - fee)
    credit("revenue:fees", fee)
}

