class CsvLine {
    private val fields = mutableListOf<String>()
    fun field(value: Any) { fields += value.toString() }
    fun build(): String = fields.joinToString(",")
}

// the parameter type CsvLine.() -> Unit is what makes the builder `this` inside the braces
fun csvLine(block: CsvLine.() -> Unit): String = CsvLine().apply(block).build()

val line = csvLine { field("pay_7"); field(1_999); field("EUR") }   // pay_7,1999,EUR

